package com.disciplina.controller;
import com.disciplina.dto.citacion.*; import com.disciplina.service.CitacionService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/citaciones") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('RECTOR', 'ORIENTADOR')")
public class CitacionController { private final CitacionService service; @PostMapping public CitacionResponseDTO crear(@Valid @RequestBody CrearCitacionDTO dto, Authentication a){return service.crearCitacion(dto,a.getName());} @GetMapping("/incidente/{id}") public List<CitacionResponseDTO> listar(@PathVariable Integer id){return service.listarPorIncidente(id);} }
